<?php
declare(strict_types=1);
namespace Architex\Http\Controller;
use Architex\Http\Request;use Architex\Http\Response;use Architex\Platform\Environment\RegulatoryCaseException;use Architex\Platform\Environment\RegulatoryCaseService;use Architex\Platform\Identity\AuthenticatedIdentity;use JsonException;
final readonly class RegulatoryCaseController
{
    public function __construct(private RegulatoryCaseService$service){}
    public function index(Request$r):Response{return$this->read($r,fn(array$s):array=>$this->service->list($s[0],$s[1],$this->id($r,'projectId','regulatory_project_not_found'),is_string($r->query('type'))?$r->query('type'):null));}
    public function show(Request$r):Response{return$this->read($r,fn(array$s):array=>$this->service->get($s[0],$s[1],$this->id($r,'caseId','regulatory_case_not_found')));}
    public function create(Request$r):Response{return$this->write($r,function(array$b,array$s)use($r):Response{$b['projectId']=$this->id($r,'projectId','regulatory_project_not_found');return Response::success($this->service->create($s[0],$s[1],$s[2],$b),status:201);});}
    public function evidence(Request$r):Response{return$this->write($r,fn(array$b,array$s):Response=>Response::success($this->service->addEvidence($s[0],$s[1],$s[2],$this->id($r,'caseId','regulatory_case_not_found'),$this->version($b),$b),status:201));}
    public function determine(Request$r):Response{return$this->write($r,fn(array$b,array$s):Response=>Response::success($this->service->determine($s[0],$s[1],$s[2],$this->id($r,'caseId','regulatory_case_not_found'),$this->version($b),($b['humanConfirmed']??false)===true,is_string($b['professionalRole']??null)?$b['professionalRole']:'',is_string($b['route']??null)?$b['route']:'',is_string($b['reason']??null)?$b['reason']:'',is_string($b['externalReference']??null)?$b['externalReference']:'')));}
    public function export(Request$r):Response{try{$s=$this->scope($r);if($s instanceof Response)return$s;$format=$r->attribute('format');if(!is_string($format))throw new RegulatoryCaseException('regulatory_export_format_invalid');$file=$this->service->export($s[0],$s[1],$this->id($r,'caseId','regulatory_case_not_found'),$format);return Response::binary($file['content'],$file['mimeType'],['Content-Disposition'=>'attachment; filename="'.addcslashes($file['filename'],'"\\').'"','Content-Length'=>(string)strlen($file['content']),'X-Content-Sha256'=>$file['sha256'],'Cache-Control'=>'private, no-store']);}catch(RegulatoryCaseException$e){return$this->error($e);}}
    /** @param callable(array{string,string,string}):array<mixed>$op */private function read(Request$r,callable$op):Response{try{$s=$this->scope($r);return$s instanceof Response?$s:Response::success($op($s));}catch(RegulatoryCaseException$e){return$this->error($e);}}/** @param callable(array<string,mixed>,array{string,string,string}):Response$op */private function write(Request$r,callable$op):Response{try{$s=$this->scope($r);if($s instanceof Response)return$s;return$op($r->jsonBody(),$s);}catch(JsonException){return Response::error(400,'invalid_json','Request body must contain valid JSON.');}catch(RegulatoryCaseException$e){return$this->error($e);}}/** @return array{string,string,string}|Response */private function scope(Request$r):array|Response{$o=$r->attribute('organisationId');$i=$r->attribute('identity');$role=$r->attribute('role');return is_string($o)&&$i instanceof AuthenticatedIdentity&&is_string($role)?[$o,$i->userId,$role]:Response::error(401,'authentication_required','Authentication is required.');}private function id(Request$r,string$n,string$e):string{$v=$r->attribute($n);if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new RegulatoryCaseException($e);return strtolower($v);}private function version(array$b):int{$v=$b['expectedVersion']??null;if(!is_int($v)||$v<1)throw new RegulatoryCaseException('regulatory_version_required');return$v;}private function error(RegulatoryCaseException$e):Response{$status=match($e->reason){'regulatory_project_not_found','regulatory_case_not_found','regulatory_evidence_not_found'=>404,'regulatory_permission_denied','regulatory_determination_role_denied'=>403,'regulatory_case_number_exists','regulatory_version_conflict','regulatory_case_determined'=>409,'regulatory_integrity_failed'=>503,default=>422};return Response::error($status,$e->reason,'The environmental or heritage request could not be completed.');}
}
